from sim import Sim
import numpy as np, mujoco
from attempt_grasp import solve_arm_position

def run(z, close_ctrl):
    sim=Sim(); q=sim.data.qpos[:7].copy()
    for _ in range(40):
        sim.data.ctrl[:] = 0; sim.data.ctrl[7]=255; sim.step(1)
    q = sim.data.qpos[:7].copy()
    q_low = solve_arm_position(sim, np.array([0.59,0.00,z]), q)
    for i in range(180):
        t=(i+1)/180
        qi=(1-t)*q + t*q_low
        sim.data.ctrl[:7]=qi; sim.data.ctrl[7]=255; sim.step(1)
    for _ in range(120):
        sim.data.ctrl[:7]=q_low; sim.data.ctrl[7]=close_ctrl; sim.step(1)
    for _ in range(500):
        sim.data.ctrl[:7]=q_low; sim.data.ctrl[7]=close_ctrl; sim.step(1)
    count=0
    for _ in range(500):
        sim.data.ctrl[:7]=q_low; sim.data.ctrl[7]=close_ctrl; sim.step(1)
        hit=False
        for ci in range(sim.data.ncon):
            c=sim.data.contact[ci]
            if (c.geom1==83 and c.geom2 in range(66,82)) or (c.geom2==83 and c.geom1 in range(66,82)):
                hit=True; break
        count += int(hit)
    return sim.cup_position(), count/500

for z in [0.42,0.40]:
    for ctrl in [130,140,150,160,170,180,190]:
        pos, frac = run(z, ctrl)
        print('z',z,'ctrl',ctrl,'pos',np.round(pos,4),'frac',frac)
